CREATE TABLE public.workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 120), kind text NOT NULL DEFAULT 'personal' CHECK(kind IN ('personal','team')), owner_id uuid NOT NULL REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.workspaces TO authenticated; GRANT ALL ON public.workspaces TO service_role;
ALTER TABLE public.workspaces ENABLE ROW LEVEL SECURITY;
CREATE POLICY workspace_owner_read ON public.workspaces FOR SELECT TO authenticated USING(owner_id=auth.uid());
CREATE TABLE public.workspace_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('owner','admin','member','viewer')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,user_id));
GRANT SELECT ON public.workspace_members TO authenticated; GRANT ALL ON public.workspace_members TO service_role;
ALTER TABLE public.workspace_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY membership_self_read ON public.workspace_members FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.workspace_role(p_workspace uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT role FROM public.workspace_members WHERE workspace_id=p_workspace AND user_id=auth.uid() $$;
REVOKE ALL ON FUNCTION public.workspace_role(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.workspace_role(uuid) TO authenticated;
CREATE POLICY workspace_member_read ON public.workspaces FOR SELECT TO authenticated USING(public.workspace_role(id) IS NOT NULL);
CREATE POLICY workspace_manager_edit ON public.workspaces FOR UPDATE TO authenticated USING(public.workspace_role(id) IN ('owner','admin')) WITH CHECK(public.workspace_role(id) IN ('owner','admin'));
CREATE POLICY workspace_roster_read ON public.workspace_members FOR SELECT TO authenticated USING(public.workspace_role(workspace_id) IS NOT NULL);
CREATE TABLE public.projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE, name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 200), description text NOT NULL DEFAULT '', category text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'Planning' CHECK(status IN ('Planning','Active','On Hold','Completed','Archived')), priority text NOT NULL DEFAULT 'Medium' CHECK(priority IN ('Low','Medium','High','Urgent')), owner_id uuid NOT NULL REFERENCES public.profiles(id), created_by uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), start_date date, due_date date, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,workspace_id), FOREIGN KEY(workspace_id,owner_id) REFERENCES public.workspace_members(workspace_id,user_id), CHECK(due_date IS NULL OR start_date IS NULL OR due_date>=start_date));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.projects TO authenticated; GRANT ALL ON public.projects TO service_role;
ALTER TABLE public.projects ENABLE ROW LEVEL SECURITY;
CREATE POLICY project_read ON public.projects FOR SELECT TO authenticated USING(public.workspace_role(workspace_id) IS NOT NULL);
CREATE POLICY project_create ON public.projects FOR INSERT TO authenticated WITH CHECK(public.workspace_role(workspace_id) IN ('owner','admin','member') AND created_by=auth.uid());
CREATE POLICY project_edit ON public.projects FOR UPDATE TO authenticated USING(public.workspace_role(workspace_id) IN ('owner','admin','member')) WITH CHECK(public.workspace_role(workspace_id) IN ('owner','admin','member'));
CREATE POLICY project_delete ON public.projects FOR DELETE TO authenticated USING(public.workspace_role(workspace_id) IN ('owner','admin') OR (public.workspace_role(workspace_id)='member' AND owner_id=auth.uid()));
CREATE TABLE public.project_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL, workspace_id uuid NOT NULL, user_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,user_id), FOREIGN KEY(project_id,workspace_id) REFERENCES public.projects(id,workspace_id) ON DELETE CASCADE, FOREIGN KEY(workspace_id,user_id) REFERENCES public.workspace_members(workspace_id,user_id) ON DELETE CASCADE);
GRANT SELECT,INSERT,DELETE ON public.project_members TO authenticated; GRANT ALL ON public.project_members TO service_role;
ALTER TABLE public.project_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY project_members_read ON public.project_members FOR SELECT TO authenticated USING(public.workspace_role(workspace_id) IS NOT NULL);
CREATE POLICY project_members_add ON public.project_members FOR INSERT TO authenticated WITH CHECK(public.workspace_role(workspace_id) IN ('owner','admin','member'));
CREATE POLICY project_members_remove ON public.project_members FOR DELETE TO authenticated USING(public.workspace_role(workspace_id) IN ('owner','admin','member'));
CREATE TABLE public.tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE, project_id uuid NOT NULL, title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 300), description text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'todo' CHECK(status IN ('backlog','todo','doing','review','done')), priority text NOT NULL DEFAULT 'Medium' CHECK(priority IN ('Low','Medium','High','Urgent')), assignee_id uuid, created_by uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), start_date date, due_date date, estimated_effort numeric CHECK(estimated_effort>=0), actual_effort numeric CHECK(actual_effort>=0), tags text[] NOT NULL DEFAULT '{}', version integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(project_id,workspace_id) REFERENCES public.projects(id,workspace_id) ON DELETE CASCADE, FOREIGN KEY(workspace_id,assignee_id) REFERENCES public.workspace_members(workspace_id,user_id), CHECK(due_date IS NULL OR start_date IS NULL OR due_date>=start_date));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.tasks TO authenticated; GRANT ALL ON public.tasks TO service_role;
ALTER TABLE public.tasks ENABLE ROW LEVEL SECURITY;
CREATE POLICY task_read ON public.tasks FOR SELECT TO authenticated USING(public.workspace_role(workspace_id) IS NOT NULL);
CREATE POLICY task_create ON public.tasks FOR INSERT TO authenticated WITH CHECK(public.workspace_role(workspace_id) IN ('owner','admin','member') AND created_by=auth.uid());
CREATE POLICY task_edit ON public.tasks FOR UPDATE TO authenticated USING(public.workspace_role(workspace_id) IN ('owner','admin','member')) WITH CHECK(public.workspace_role(workspace_id) IN ('owner','admin','member'));
CREATE POLICY task_delete ON public.tasks FOR DELETE TO authenticated USING(public.workspace_role(workspace_id) IN ('owner','admin','member'));
CREATE TABLE public.task_activity_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE, project_id uuid NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE, task_id uuid, actor_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL, event text NOT NULL, task_title text NOT NULL, changes jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.task_activity_logs TO authenticated; GRANT ALL ON public.task_activity_logs TO service_role;
ALTER TABLE public.task_activity_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY activity_read ON public.task_activity_logs FOR SELECT TO authenticated USING(public.workspace_role(workspace_id) IS NOT NULL);
CREATE INDEX projects_workspace_updated ON public.projects(workspace_id,updated_at DESC); CREATE INDEX tasks_workspace_project ON public.tasks(workspace_id,project_id); CREATE INDEX tasks_assignee_due ON public.tasks(workspace_id,assignee_id,due_date); CREATE INDEX activity_project_created ON public.task_activity_logs(project_id,created_at DESC); CREATE INDEX workspace_members_user ON public.workspace_members(user_id);
CREATE FUNCTION public.guard_execution_record() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' THEN IF NEW.workspace_id<>OLD.workspace_id OR NEW.created_by<>OLD.created_by THEN RAISE EXCEPTION 'Immutable workspace and creator'; END IF; IF TG_TABLE_NAME='tasks' THEN IF NEW.version<>OLD.version THEN RAISE EXCEPTION 'Task changed elsewhere; refresh before saving'; END IF; NEW.version:=OLD.version+1; END IF; END IF; NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER project_guard BEFORE UPDATE ON public.projects FOR EACH ROW EXECUTE FUNCTION public.guard_execution_record(); CREATE TRIGGER task_guard BEFORE UPDATE ON public.tasks FOR EACH ROW EXECUTE FUNCTION public.guard_execution_record();
CREATE FUNCTION public.guard_workspace_owner() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.owner_id<>OLD.owner_id THEN RAISE EXCEPTION 'Workspace ownership is immutable'; END IF; NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER workspace_guard BEFORE UPDATE ON public.workspaces FOR EACH ROW EXECUTE FUNCTION public.guard_workspace_owner();
CREATE FUNCTION public.log_task_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.tasks; e text; BEGIN IF TG_OP='DELETE' THEN r:=OLD; e:='Task deleted'; ELSIF TG_OP='INSERT' THEN r:=NEW; e:='Task created'; ELSE r:=NEW; e:=CASE WHEN NEW.status IS DISTINCT FROM OLD.status THEN CASE WHEN NEW.status='done' THEN 'Task completed' ELSE 'Status changed' END WHEN NEW.assignee_id IS DISTINCT FROM OLD.assignee_id THEN 'Task assigned' WHEN NEW.priority IS DISTINCT FROM OLD.priority THEN 'Priority changed' ELSE 'Task updated' END; END IF; INSERT INTO public.task_activity_logs(workspace_id,project_id,task_id,actor_id,event,task_title,changes) SELECT r.workspace_id,r.project_id,r.id,auth.uid(),e,r.title,jsonb_build_object('before',CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END,'after',CASE WHEN TG_OP='DELETE' THEN NULL ELSE to_jsonb(NEW) END) WHERE EXISTS(SELECT 1 FROM public.projects WHERE id=r.project_id); RETURN r; END $$;
CREATE TRIGGER task_activity AFTER INSERT OR UPDATE OR DELETE ON public.tasks FOR EACH ROW EXECUTE FUNCTION public.log_task_change();
CREATE FUNCTION public.create_workspace(p_name text,p_kind text DEFAULT 'personal') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; INSERT INTO public.workspaces(name,kind,owner_id) VALUES(trim(p_name),p_kind,auth.uid()) RETURNING id INTO w; INSERT INTO public.workspace_members(workspace_id,user_id,role) VALUES(w,auth.uid(),'owner'); RETURN w; END $$;
REVOKE ALL ON FUNCTION public.create_workspace(text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_workspace(text,text) TO authenticated;
CREATE FUNCTION public.manage_workspace_member(p_workspace uuid,p_email text,p_role text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid; current_role text; caller_role text; BEGIN caller_role:=public.workspace_role(p_workspace); IF caller_role IS NULL OR caller_role NOT IN ('owner','admin') THEN RAISE EXCEPTION 'Not authorized'; END IF; IF p_role NOT IN ('admin','member','viewer','remove') THEN RAISE EXCEPTION 'Invalid role'; END IF; SELECT id INTO u FROM public.profiles WHERE lower(email)=lower(trim(p_email)); IF u IS NULL THEN RAISE EXCEPTION 'Member must have an existing Planz account'; END IF; SELECT role INTO current_role FROM public.workspace_members WHERE workspace_id=p_workspace AND user_id=u; IF current_role='owner' OR (caller_role='admin' AND (current_role='admin' OR p_role='admin')) THEN RAISE EXCEPTION 'Only owner can manage admins; owner cannot be removed'; END IF; IF p_role='remove' THEN DELETE FROM public.workspace_members WHERE workspace_id=p_workspace AND user_id=u; ELSE INSERT INTO public.workspace_members(workspace_id,user_id,role) VALUES(p_workspace,u,p_role) ON CONFLICT(workspace_id,user_id) DO UPDATE SET role=excluded.role,updated_at=now(); END IF; END $$;
REVOKE ALL ON FUNCTION public.manage_workspace_member(uuid,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.manage_workspace_member(uuid,text,text) TO authenticated;
CREATE FUNCTION public.workspace_roster(p_workspace uuid) RETURNS TABLE(user_id uuid,role text,full_name text,email text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT m.user_id,m.role,p.full_name,p.email FROM public.workspace_members m JOIN public.profiles p ON p.id=m.user_id WHERE m.workspace_id=p_workspace AND public.workspace_role(p_workspace) IS NOT NULL $$;
REVOKE ALL ON FUNCTION public.workspace_roster(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.workspace_roster(uuid) TO authenticated;
CREATE FUNCTION public.duplicate_project(p_project uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.projects; n uuid; BEGIN SELECT * INTO p FROM public.projects WHERE id=p_project; IF p.id IS NULL OR public.workspace_role(p.workspace_id) IS NULL OR public.workspace_role(p.workspace_id) NOT IN ('owner','admin','member') THEN RAISE EXCEPTION 'Not authorized'; END IF; INSERT INTO public.projects(workspace_id,name,description,category,priority,owner_id,created_by,start_date,due_date) VALUES(p.workspace_id,left(p.name,190)||' (copy)',p.description,p.category,p.priority,p.owner_id,auth.uid(),p.start_date,p.due_date) RETURNING id INTO n; INSERT INTO public.project_members(project_id,workspace_id,user_id) SELECT n,workspace_id,user_id FROM public.project_members WHERE project_id=p_project; INSERT INTO public.tasks(workspace_id,project_id,title,description,status,priority,assignee_id,created_by,start_date,due_date,estimated_effort,tags) SELECT workspace_id,n,title,description,'todo',priority,assignee_id,auth.uid(),start_date,due_date,estimated_effort,tags FROM public.tasks WHERE project_id=p_project; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.duplicate_project(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.duplicate_project(uuid) TO authenticated;